'use strict';

// The WebAssembly module, generated by wasm-bindgen for Node and loaded synchronously.
const wasm = require('./wasm/rely_office_wasm.js');

/** An error of rely-office, with the stable code of what went wrong. */
class RelyOfficeError extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'RelyOfficeError';
    this.code = code;
  }
}

const CODED_MESSAGE = /^([A-Z_]+): ([\s\S]*)$/;

/** Run a wasm call, turning its coded `Error` into a `RelyOfficeError`. */
function call(operation) {
  try {
    return operation();
  } catch (error) {
    const match = error instanceof Error ? CODED_MESSAGE.exec(error.message) : null;
    if (match) {
      throw new RelyOfficeError(match[1], match[2]);
    }
    throw error;
  }
}

/** The document as a `Uint8Array`; a Node `Buffer` already is one. */
function toBytes(input) {
  if (input instanceof Uint8Array) {
    return input;
  }
  if (input instanceof ArrayBuffer) {
    return new Uint8Array(input);
  }
  if (ArrayBuffer.isView(input)) {
    return new Uint8Array(input.buffer, input.byteOffset, input.byteLength);
  }
  throw new TypeError('rely-office: the document must be a Uint8Array, a Buffer or an ArrayBuffer');
}

function toFileName(fileName) {
  return fileName === undefined || fileName === null ? undefined : String(fileName);
}

function toLimitsJson(limits) {
  return limits === undefined || limits === null ? undefined : JSON.stringify(limits);
}

function detectFormat(bytes, fileName) {
  return wasm.detectFormat(toBytes(bytes), toFileName(fileName));
}

function extractText(bytes, fileName, limits) {
  const json = call(() =>
    wasm.extractTextJson(toBytes(bytes), toFileName(fileName), toLimitsJson(limits)),
  );
  return JSON.parse(json);
}

function readSheets(bytes, fileName, limits) {
  const json = call(() =>
    wasm.readSheetsJson(toBytes(bytes), toFileName(fileName), toLimitsJson(limits)),
  );
  return JSON.parse(json);
}

function readDocumentTree(bytes, limits) {
  const handle = call(() => wasm.readDocumentTreeHandle(toBytes(bytes), toLimitsJson(limits)));
  try {
    const tree = JSON.parse(handle.json);
    tree.media = tree.media.map((item) => ({
      index: item.index,
      contentType: item.contentType,
      bytes: handle.takeMediaBytes(item.index) ?? new Uint8Array(0),
    }));
    return tree;
  } finally {
    handle.free();
  }
}

module.exports = {
  RelyOfficeError,
  detectFormat,
  extractText,
  readSheets,
  readDocumentTree,
  version: wasm.version(),
};
